const WHATSAPP_PHONE = '8801887924939';

let currentSelectedProduct = null;
let currentSelectedVariation = null;
let currentPaymentMethod = 'bKash';

// Initialize on DOM load
document.addEventListener('DOMContentLoaded', () => {
  renderPriceTable(PRICE_ROWS);
  setupSearch();
  setupFilterTabs();
  setupModalEvents();
});

// Filter Tabs Logic
function setTab(category, btn) {
  document.querySelectorAll('.tab-btn').forEach(b => {
    b.classList.remove('active', 'bg-primary-container', 'text-on-primary-container');
    b.classList.add('glass-pill', 'text-on-surface-variant');
  });
  btn.classList.add('active', 'bg-primary-container', 'text-on-primary-container');
  btn.classList.remove('glass-pill', 'text-on-surface-variant');

  const items = document.querySelectorAll('.product-item');
  let visible = 0;
  items.forEach(item => {
    const itemCat = item.getAttribute('data-category');
    if (category === 'all' || itemCat === category) {
      item.style.display = 'flex';
      visible++;
    } else {
      item.style.display = 'none';
    }
  });
  const countEl = document.getElementById('activeCountText');
  if (countEl) countEl.innerText = `Showing ${visible} of 19 official licenses`;
}
window.setTab = setTab;

// Search Logic
function handleSearch(query) {
  const q = query.toLowerCase().trim();
  const items = document.querySelectorAll('.product-item');
  let visible = 0;
  items.forEach(item => {
    const title = (item.getAttribute('data-title') || '').toLowerCase();
    const cat = (item.getAttribute('data-category') || '').toLowerCase();
    if (!q || title.includes(q) || cat.includes(q)) {
      item.style.display = 'flex';
      visible++;
    } else {
      item.style.display = 'none';
    }
  });
  const countEl = document.getElementById('activeCountText');
  if (countEl) countEl.innerText = `Showing ${visible} matching products`;
}
window.handleSearch = handleSearch;

function setupSearch() {
  const input = document.getElementById('searchInput');
  if (input) {
    input.addEventListener('input', (e) => handleSearch(e.target.value));
  }
}

function setupFilterTabs() {
  // handled via setTab
}

// ================= MODAL LOGIC (SubStoreBD Feature) =================
function openProductModal(productId) {
  const prod = PRODUCTS_DATA.find(p => p.id == productId);
  if (!prod) return;

  currentSelectedProduct = prod;
  currentSelectedVariation = prod.variations[0] || null;

  const modal = document.getElementById('productModal');
  const modalTitle = document.getElementById('modalTitle');
  const modalCategory = document.getElementById('modalCategory');
  const modalDesc = document.getElementById('modalDesc');
  const modalVariationsList = document.getElementById('modalVariationsList');

  modalTitle.innerText = prod.name;
  modalCategory.innerText = prod.categories.join(', ') || 'Subscription';
  modalDesc.innerText = prod.short_description || 'Instant automated dispatch via WhatsApp & Email.';
  const modalDetailLink = document.getElementById('modalDetailLink');
  if (modalDetailLink) {
    modalDetailLink.href = 'product.html?id=' + prod.id;
  }

  // Render variations
  modalVariationsList.innerHTML = '';
  if (prod.variations && prod.variations.length > 0) {
    prod.variations.forEach((v, index) => {
      const isSelected = index === 0;
      const optCard = document.createElement('div');
      optCard.className = `variation-option-card flex items-center justify-between p-3.5 rounded-xl border cursor-pointer transition-all ${
        isSelected
          ? 'border-primary-container bg-primary-container/10 text-white shadow-[0_0_12px_rgba(0,229,255,0.15)]'
          : 'border-white/10 bg-white/[0.03] text-on-surface-variant hover:border-white/30 hover:bg-white/[0.06]'
      }`;
      
      const saleP = v.price !== null ? `৳${v.price.toLocaleString()}` : '৳0';
      const regP = v.regular_price ? `৳${v.regular_price.toLocaleString()}` : '';
      const saveP = (v.regular_price && v.regular_price > v.price) ? `Save ৳${v.regular_price - v.price}` : '';

      optCard.innerHTML = `
        <div class="flex items-center gap-3">
          <div class="w-4 h-4 rounded-full border flex items-center justify-center ${isSelected ? 'border-primary-container' : 'border-outline'}">
            <div class="w-2 h-2 rounded-full ${isSelected ? 'bg-primary-container' : 'bg-transparent'}"></div>
          </div>
          <div>
            <div class="text-sm font-semibold text-white">${v.option}</div>
            <div class="text-[11px] text-tertiary">${v.is_in_stock ? 'In Stock (Instant Dispatch)' : 'Out of Stock'}</div>
          </div>
        </div>
        <div class="text-right">
          <div class="text-base font-bold font-display text-white">${saleP}</div>
          ${regP ? `<div class="text-[11px] text-outline line-through">${regP}</div>` : ''}
          ${saveP ? `<span class="text-[10px] px-1.5 py-0.5 rounded bg-emerald-500/20 text-emerald-400 font-semibold">${saveP}</span>` : ''}
        </div>
      `;

      optCard.addEventListener('click', () => {
        currentSelectedVariation = v;
        document.querySelectorAll('.variation-option-card').forEach(c => {
          c.classList.remove('border-primary-container', 'bg-primary-container/10', 'text-white', 'shadow-[0_0_12px_rgba(0,229,255,0.15)]');
          c.classList.add('border-white/10', 'bg-white/[0.03]', 'text-on-surface-variant');
          c.querySelector('.w-4').classList.replace('border-primary-container', 'border-outline');
          c.querySelector('.w-2').classList.replace('bg-primary-container', 'bg-transparent');
        });
        optCard.classList.add('border-primary-container', 'bg-primary-container/10', 'text-white', 'shadow-[0_0_12px_rgba(0,229,255,0.15)]');
        optCard.classList.remove('border-white/10', 'bg-white/[0.03]', 'text-on-surface-variant');
        optCard.querySelector('.w-4').classList.replace('border-outline', 'border-primary-container');
        optCard.querySelector('.w-2').classList.replace('bg-transparent', 'bg-primary-container');
        updateModalSummary();
      });

      modalVariationsList.appendChild(optCard);
    });
  } else {
    modalVariationsList.innerHTML = '<div class="text-sm text-outline p-4 text-center">Standard license delivery.</div>';
  }

  updateModalSummary();
  modal.classList.remove('hidden');
  modal.classList.add('flex');
}
window.openProductModal = openProductModal;

function setPaymentMethod(method, btn) {
  currentPaymentMethod = method;
  document.querySelectorAll('.pay-method-btn').forEach(b => {
    b.classList.remove('border-primary-container', 'bg-primary-container/20', 'text-white');
    b.classList.add('border-white/10', 'bg-white/[0.03]', 'text-on-surface-variant');
  });
  btn.classList.add('border-primary-container', 'bg-primary-container/20', 'text-white');
  btn.classList.remove('border-white/10', 'bg-white/[0.03]', 'text-on-surface-variant');
  updateModalSummary();
}
window.setPaymentMethod = setPaymentMethod;

function updateModalSummary() {
  const summaryPrice = document.getElementById('modalSummaryPrice');
  const summaryPlan = document.getElementById('modalSummaryPlan');
  if (currentSelectedVariation && summaryPrice && summaryPlan) {
    const p = currentSelectedVariation.price !== null ? `৳${currentSelectedVariation.price.toLocaleString()}` : '৳0';
    summaryPrice.innerText = p;
    summaryPlan.innerText = `${currentSelectedProduct.name} • ${currentSelectedVariation.option}`;
  }
}

function closeProductModal() {
  const modal = document.getElementById('productModal');
  if (modal) {
    modal.classList.add('hidden');
    modal.classList.remove('flex');
  }
}
window.closeProductModal = closeProductModal;

function setupModalEvents() {
  const modal = document.getElementById('productModal');
  if (modal) {
    modal.addEventListener('click', (e) => {
      if (e.target === modal) closeProductModal();
    });
  }
}

// Dispatch Order to WhatsApp (Exact SubStoreBD Flow)
function sendWhatsAppOrder() {
  if (!currentSelectedProduct || !currentSelectedVariation) return;

  const phoneInput = document.getElementById('customerPhone');
  const customerPhone = phoneInput ? phoneInput.value.trim() : '';

  const service = currentSelectedProduct.name;
  const plan = currentSelectedVariation.option;
  const price = currentSelectedVariation.price !== null ? `৳${currentSelectedVariation.price}` : 'Contact Us';

  const text = `Hello DigitalSubShop! 🎬\n\nI want to order:\n*Service:* ${service}\n*Plan:* ${plan}\n*Price:* ${price}\n*Payment Method:* ${currentPaymentMethod}${customerPhone ? `\n*My Phone/Account:* ${customerPhone}` : ''}\n\nPlease confirm my order. Thank you!`;

  const url = `https://wa.me/${WHATSAPP_PHONE}?text=${encodeURIComponent(text)}`;
  window.open(url, '_blank');
}
window.sendWhatsAppOrder = sendWhatsAppOrder;

// Copy text utility
function copyText(str) {
  navigator.clipboard.writeText(str).then(() => {
    const toast = document.getElementById('copyToast');
    if (toast) {
      toast.classList.remove('opacity-0', 'pointer-events-none');
      setTimeout(() => toast.classList.add('opacity-0', 'pointer-events-none'), 2000);
    }
  });
}
window.copyText = copyText;

// ================= PRICING TABLE (All 79 Options) =================
function renderPriceTable(rows) {
  const tbody = document.getElementById('pricingTableBody');
  const empty = document.getElementById('pricingEmpty');
  if (!tbody) return;

  if (!rows || rows.length === 0) {
    tbody.innerHTML = '';
    if (empty) empty.classList.remove('hidden');
    return;
  }
  if (empty) empty.classList.add('hidden');

  tbody.innerHTML = rows.map(r => {
    const saleNum = Number(r['Sale Price (BDT)']);
    const regNum = Number(r['Regular Price (BDT)']);
    const discountNum = Number(r['Discount (BDT)']);

    const saleDisplay = !isNaN(saleNum) && saleNum > 0 ? `৳${saleNum.toLocaleString()}` : '৳0';
    const regDisplay = !isNaN(regNum) && regNum > saleNum ? `৳${regNum.toLocaleString()}` : '—';
    const saveDisplay = !isNaN(discountNum) && discountNum > 0 ? `Save ৳${discountNum.toLocaleString()}` : '—';
    const inStock = r['Stock Status'] === 'In Stock';

    const orderText = encodeURIComponent(`Hello DigitalSubShop! 🎬\n\nI want to order:\n*Service:* ${r['Product Name']}\n*Plan:* ${r['Variation / Plan Option']}\n*Price:* ${saleDisplay}\n\nPlease confirm my order. Thank you!`);
    const waUrl = `https://wa.me/${WHATSAPP_PHONE}?text=${orderText}`;

    return `
      <tr class="border-b border-white/[0.04] hover:bg-white/[0.02] transition-colors">
        <td class="py-4 px-4 font-semibold text-white text-xs sm:text-sm">${r['Product Name']}</td>
        <td class="py-4 px-4 text-xs text-on-surface-variant hidden md:table-cell">${r['Category'] || 'General'}</td>
        <td class="py-4 px-4 text-xs sm:text-sm text-cyan-200">${r['Variation / Plan Option']}</td>
        <td class="py-4 px-4 text-xs text-outline line-through hidden sm:table-cell">${regDisplay}</td>
        <td class="py-4 px-4 font-display font-bold text-sm sm:text-base text-white">${saleDisplay}</td>
        <td class="py-4 px-4 text-xs font-semibold text-tertiary hidden lg:table-cell">${saveDisplay}</td>
        <td class="py-4 px-4 text-xs">
          <span class="px-2 py-0.5 rounded-full text-[10px] font-semibold ${inStock ? 'bg-emerald-500/15 text-emerald-400' : 'bg-red-500/15 text-red-400'}">
            ${r['Stock Status']}
          </span>
        </td>
        <td class="py-4 px-4 text-right">
          ${inStock && saleNum > 0 ? `
            <a href="${waUrl}" target="_blank" class="inline-flex items-center gap-1 px-3 py-1.5 rounded-lg bg-primary-container text-on-primary-container font-semibold text-[11px] uppercase tracking-wider hover:brightness-110 transition-all">
              <span class="material-symbols-outlined text-[13px]">bolt</span>
              Order
            </a>
          ` : `
            <span class="text-xs text-outline">Unavailable</span>
          `}
        </td>
      </tr>
    `;
  }).join('');
}

function applyTableFilter() {
  const query = (document.getElementById('tableSearchInput')?.value || '').toLowerCase().trim();
  const cat = document.getElementById('tableCatSelect')?.value || 'all';

  const filtered = PRICE_ROWS.filter(r => {
    const name = (r['Product Name'] || '').toLowerCase();
    const opt = (r['Variation / Plan Option'] || '').toLowerCase();
    const c = (r['Category'] || '').toLowerCase();

    const matchesQuery = !query || name.includes(query) || opt.includes(query);
    const matchesCat = (cat === 'all') || c.includes(cat);
    return matchesQuery && matchesCat;
  });

  renderPriceTable(filtered);
}
window.applyTableFilter = applyTableFilter;

// Mobile Menu Toggle
function toggleMobileMenu() {
  const menu = document.getElementById('mobileMenu');
  if (menu) menu.classList.toggle('hidden');
}
window.toggleMobileMenu = toggleMobileMenu;

function openProductPage(id) {
  window.location.href = `product.html?id=${id}`;
}

window.toggleMobileMenu = toggleMobileMenu;
window.openProductPage = openProductPage;
